Here's a recreated Pokémon battle UI in a single-page, self-contained HTML file. I've aimed to capture the nostalgic feel of a classic battle while adding some creative twists. Have fun interacting with it!

**Pokémon Battle UI**

**[Click to start the battle!](javascript:startBattle())**

<div id="battle-ui" style="display: none;">
  <h1>Pokémon Battle</h1>
  <div id="player-info">
    <h2>Trainer: <span id="player-name">You</span></h2>
    <p>Party:</p>
    <ul id="player-party">
      <li>Pikachu (Level 10)</li>
      <li>Charmander (Level 10)</li>
      <li>Squirtle (Level 10)</li>
    </ul>
  </div>
  <div id="opponent-info">
    <h2>Opponent: <span id="opponent-name">Wild Pidgey</span></h2>
    <p>Pokémon:</p>
    <ul id="opponent-party">
      <li>Pidgey (Level 10)</li>
    </ul>
  </div>
  <div id="battle-log">
    <h2>Battle Log</h2>
    <ul id="battle-log-list"></ul>
  </div>
  <div id="battle-actions">
    <button id="attack-button" onclick="attack()">Attack</button>
    <button id="pokemon-button" onclick="switchPokemon()">Switch Pokémon</button>
    <button id="run-button" onclick="run()">Run</button>
  </div>
  <div id="pokemon-stats">
    <h2>Current Pokémon:</h2>
    <ul id="pokemon-stats-list">
      <li>HP: <span id="current-hp">90</span>/90</li>
      <li>Attack: <span id="current-attack">85</span></li>
      <li>Defense: <span id="current-defense">60</span></li>
    </ul>
  </div>
</div>

<script>
  let currentPlayerPokemon = 0;
  let currentOpponentPokemon = 0;
  let battleLog = [];

  function startBattle() {
    document.getElementById("battle-ui").style.display = "block";
    document.getElementById("player-name").innerHTML = prompt("Enter your trainer name:");
    generateOpponent();
  }

  function generateOpponent() {
    const opponentPokemon = ["Pidgey", "Rattata", "Spearow"];
    const randomIndex = Math.floor(Math.random() * opponentPokemon.length);
    document.getElementById("opponent-name").innerHTML = "Wild " + opponentPokemon[randomIndex];
  }

  function attack() {
    const playerPokemon = getPlayerPokemon();
    const opponentPokemon = getOpponentPokemon();
    const attackDamage = calculateAttackDamage(playerPokemon, opponentPokemon);
    opponentPokemon.hp -= attackDamage;
    battleLog.push(`${playerPokemon.name} attacks ${opponentPokemon.name} for ${attackDamage} damage!`);
    updateBattleLog();
    checkForFaint();
  }

  function switchPokemon() {
    currentPlayerPokemon = (currentPlayerPokemon + 1) % 3;
    updatePokemonStats();
  }

  function run() {
    battleLog.push("You ran away from the battle!");
    updateBattleLog();
    endBattle();
  }

  function getPlayerPokemon() {
    const playerPokemons = ["Pikachu", "Charmander", "Squirtle"];
    return {
      name: playerPokemons[currentPlayerPokemon],
      hp: 90,
      attack: 85,
      defense: 60
    };
  }

  function getOpponentPokemon() {
    return {
      name: document.getElementById("opponent-name").innerHTML,
      hp: 90,
      attack: 45,
      defense: 40
    };
  }

  function calculateAttackDamage(attacker, defender) {
    return Math.floor((attacker.attack * 2) / defender.defense);
  }

  function updateBattleLog() {
    const battleLogList = document.getElementById("battle-log-list");
    battleLogList.innerHTML = "";
    battleLog.forEach((logEntry) => {
      const logItem = document.createElement("li");
      logItem.textContent = logEntry;
      battleLogList.appendChild(logItem);
    });
  }

  function updatePokemonStats() {
    const pokemonStatsList = document.getElementById("pokemon-stats-list");
    const currentPokemon = getPlayerPokemon();
    pokemonStatsList.innerHTML = "";
    pokemonStatsList.appendChild(document.createElement("li")).textContent = `HP: ${currentPokemon.hp}/${currentPokemon.hp}`;
    pokemonStatsList.appendChild(document.createElement("li")).textContent = `Attack: ${currentPokemon.attack}`;
    pokemonStatsList.appendChild(document.createElement("li")).textContent = `Defense: ${currentPokemon.defense}`;
  }

  function checkForFaint() {
    const opponentPokemon = getOpponentPokemon();
    if (opponentPokemon.hp <= 0) {
      battleLog.push(`${opponentPokemon.name} fainted! You win!`);
      updateBattleLog();
      endBattle();
    }
  }

  function endBattle() {
    document.getElementById("battle-ui").style.display = "none";
    alert("Battle ended!");
  }
</script>

