function makePoke(key, lv){
  const d = DEX[key];
  const p = {key, name:d.name, types:d.types, level:lv,
    atk:d.atk+lv, def:d.def+lv, spd:d.spd+lv, maxhp:d.hp+lv*3,
    moves:d.moves.slice(), pp:{}, stAtk:0, stDef:0};
  p.moves.forEach(m => p.pp[m] = MOVES[m].pp);
  p.hp = p.maxhp;
  return p;
}
const statOf = (p, w) => (w==='atk'?p.atk:p.def) * ((w==='atk'?p.stAtk:p.stDef) < 0 ? ((w==='atk'?p.stAtk:p.stDef)===-1?0.75:0.55) : 1);

